import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class GoodFileAccess {
    public void readFile(String filename) throws Exception {
        // Define a strict base directory to prevent escaping outside of allowed paths.
        Path basePath = Paths.get("/var/data");

        // Resolve the user-provided filename against the base path safely.
        // This prevents ".." sequences from escaping the intended directory.
        Path safePath = basePath.resolve(filename).normalize();

        // Ensure the resolved path still starts with the base directory.
        if (!safePath.startsWith(basePath)) {
            throw new SecurityException("Attempted path traversal detected.");
        }

        // Now read the file securely.
        byte[] data = Files.readAllBytes(safePath);
        System.out.println("File content length: " + data.length);
    }
}
